from pydantic import BaseModel

class Verdict(BaseModel):
    category: str
    needs_human: bool

class FakeClient:
    def __init__(self):
        self.calls = 0
    def chat(self, messages, **kw):
        self.calls += 1
        # first call returns invalid (wrong type), second is valid
        content = ('{"category": "billing", "needs_human": "yes"}'
                   if self.calls == 1
                   else '{"category": "billing", "needs_human": true}')
        return type("R", (), {"content": content})()

def get_structured(client, messages, Model, max_retries=2):
    for _ in range(max_retries + 1):
        resp = client.chat(messages=messages, response_format={"type": "json_object"})
        try:
            return Model.model_validate_json(resp.content)
        except Exception as e:
            messages = messages + [
                {"role": "assistant", "content": resp.content},
                {"role": "user", "content": f"Validation failed: {e}. Return valid JSON only."},
            ]
    raise ValueError("never produced valid output")

client = FakeClient()
verdict = get_structured(client, [{"role": "user", "content": "triage this"}], Verdict)
print(verdict.category, verdict.needs_human, "in", client.calls, "calls")

