import re, json
from pydantic import BaseModel, ValidationError

class Payment(BaseModel):
    total: float        # coerces '42' -> 42.0
    paid: bool          # coerces 'false' -> False, rejects garbage

def extract_json_block(text: str) -> str:
    # tolerate prose/fences: grab the first {...} object
    m = re.search(r"\{.*\}", text, re.DOTALL)
    if not m:
        raise ValueError("no JSON object found in model output")
    return m.group(0)

def extract(reply: str) -> Payment:
    block = extract_json_block(reply)
    try:
        return Payment.model_validate_json(block)  # parse + typed validation
    except (ValidationError, json.JSONDecodeError) as e:
        raise ValueError(f"invalid payment output: {e}") from e

reply = 'Sure! Here is the data:\n```json\n{"total": "42", "paid": "false"}\n```'
p = extract(reply)
print(p.total, p.paid)   # 42.0 False  -- correct types now

