import re, json
from pydantic import BaseModel, ValidationError

def parse_validated(text: str, Model: type[BaseModel]) -> BaseModel:
    m = re.search(r"\{.*\}", text, re.DOTALL)   # first JSON object, ignore prose
    if not m:
        raise ValueError("no JSON object found in output")
    try:
        return Model.model_validate_json(m.group(0))
    except (ValidationError, json.JSONDecodeError) as e:
        raise ValueError(f"validation failed: {e}") from e

if __name__ == "__main__":
    class Verdict(BaseModel):
        category: str
        needs_human: bool
    text = 'Sure!\n```json\n{"category": "billing", "needs_human": true}\n```'
    v = parse_validated(text, Verdict)
    print(v.category, v.needs_human)
